export function validateIdentityMap(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || value.version !== 1 ||
      value.shopDomain !== EXPECTED_DOMAIN || value.merchantAccountId !== EXPECTED_MERCHANT ||
      value.idPolicy !== 'preserve-existing' || value.complete !== true ||
      typeof value.dataSourceId !== 'string' || !value.dataSourceId.trim() ||
      !/^[a-f0-9]{64}$/.test(value.sourceSnapshotSha256 || '') ||
      typeof value.reviewReference !== 'string' || !value.reviewReference.trim() ||
      !Array.isArray(value.entries) || value.entries.length === 0) {
    fail('FEED_IDENTITY_UNKNOWN: reviewed complete existing-source map required');
  }
  const entries = new Map(), externalIds = new Set(), variants = new Set();
  for (const record of value.entries) {
    if (!record || !gid(record.productId, 'Product') || !gid(record.variantId, 'ProductVariant') ||
        typeof record.handle !== 'string' || !/^[a-z0-9][a-z0-9-]*$/.test(record.handle) ||
        typeof record.feedId !== 'string' || !record.feedId.trim() ||
        Array.from(record.feedId).length > 50 || /[\u0000-\u001f\u007f]/.test(record.feedId)) {
      fail('FEED_IDENTITY_UNKNOWN: exact product/variant/handle/existing feed ID required');
    }
    if (entries.has(record.productId) || externalIds.has(record.feedId) || variants.has(record.variantId)) {
      fail('FEED_IDENTITY_CONFLICT: duplicate identity or unsupported multiple variants per product');
    }
    entries.set(record.productId, { ...record }); externalIds.add(record.feedId); variants.add(record.variantId);
