export function parseExcludedDestinations(product) {
  if (!own(product, 'excludedDestination')) fail('FEED_SOURCE_UNKNOWN: exclusion field not returned');
  const field = product.excludedDestination;
  // Explicit null from the complete exact-field response is absence, not an empty page.
  if (field === null) return [];
  if (!field || typeof field.value !== 'string') fail('FEED_SOURCE_UNKNOWN: invalid exclusion response');
  let values;
  if (field.type === 'list.single_line_text_field') {
    try { values = JSON.parse(field.value); } catch { fail('FEED_SOURCE_UNKNOWN: malformed exclusion JSON'); }
  } else if (field.type === 'single_line_text_field') values = [field.value];
  else fail('FEED_SOURCE_UNKNOWN: unsupported exclusion metafield type');
  if (!Array.isArray(values) || values.some(v => typeof v !== 'string' || !v || v !== v.trim())) {
    fail('FEED_SOURCE_UNKNOWN: exclusion is not an exact nonempty string list');
