export function validateShopIdentity(shop) {
  let url; try { url = new URL(shop?.primaryDomain?.url); } catch { fail('FEED_SHOP_UNKNOWN: primary domain unavailable'); }
  if (shop?.myshopifyDomain !== EXPECTED_SHOP || shop?.currencyCode !== 'CHF' ||
      url.protocol !== 'https:' || url.hostname !== EXPECTED_DOMAIN || url.port || url.username || url.password ||
      url.pathname !== '/' || url.search || url.hash) {
    fail('FEED_SHOP_MISMATCH: LuxeStyle/CHF identity required');
  }
}

export function sourceGtin(variant) {
  const values = variant?.barcodes;
  if (!Array.isArray(values?.edges) || values.pageInfo?.hasNextPage !== false) {
    fail('FEED_SOURCE_UNKNOWN: complete exact-variant barcode response required');
  }
  const gtins = new Set();
  for (const edge of values.edges) {
    const code = edge?.node;
    if (!code || typeof code.value !== 'string' || !code.value.trim() ||
        ![null, 'ASIN', 'EAN', 'GTIN', 'ISBN', 'NS_PID', 'UPC'].includes(code.type)) {
      fail('FEED_SOURCE_UNKNOWN: malformed or unknown barcode response');
    }
    // ASIN/NS_PID and an undeclared standard are not guessed to be GTIN/MPN.
    if (['EAN', 'GTIN', 'UPC'].includes(code.type) || code.type === 'ISBN' && /^\d{13}$/.test(code.value)) {
      if (!/^\d{8}$|^\d{12,14}$/.test(code.value)) fail('FEED_SOURCE_UNKNOWN: malformed declared GTIN');
      gtins.add(code.value);
    }
  }
  if (gtins.size > 1) fail('FEED_REVIEW_REQUIRED: multiple GTINs need an explicit reviewed selection');
  return [...gtins][0];
}

export function mappedQueries(identity) {
  const ids = [...identity.entries.keys()].map(id => id.split('/').at(-1));
  const queries = [];
  for (let i = 0; i < ids.length; i += 50) queries.push(ids.slice(i, i + 50).map(id => `id:${id}`).join(' OR '));
  return queries;
}

export function sourceProduct(product, record) {
  if (!product || product.id !== record.productId || product.handle !== record.handle || product.status !== 'ACTIVE') {
    fail('FEED_SOURCE_UNKNOWN: exact active product binding differs from reviewed map');
  }
  if (!Array.isArray(product.tags) || !product.tags.length || product.tags.some(t => typeof t !== 'string' || !t.trim())) {
    fail('FEED_SOURCE_UNKNOWN: current nonempty tags required');
  }
  if (typeof product.beschreibung !== 'string') fail('FEED_SOURCE_UNKNOWN: full current product description required for safety review');
  const v = product.variants?.edges?.[0]?.node;
  if (!v || v.id !== record.variantId || !gid(v.id, 'ProductVariant') ||
      product.variants?.edges?.length !== 1 || product.variants?.pageInfo?.hasNextPage !== false) {
    fail('FEED_VARIANT_UNKNOWN: first returned variant differs from reviewed exact mapping');
  }
  if (typeof v.availableForSale !== 'boolean') fail('FEED_SOURCE_UNKNOWN: variant sale availability missing');
  if (typeof v.price !== 'string' || !/^\d+(?:\.\d+)?$/.test(v.price) || !Number.isFinite(Number(v.price)) || Number(v.price) <= 0) {
    fail('FEED_SOURCE_UNKNOWN: finite positive exact-variant CHF price required');
  }
  if (v.compareAtPrice !== null && (typeof v.compareAtPrice !== 'string' || !/^\d+(?:\.\d+)?$/.test(v.compareAtPrice) || !Number.isFinite(Number(v.compareAtPrice)))) {
    fail('FEED_SOURCE_UNKNOWN: compare-at price response incomplete or invalid');
  }
  let url; try { url = new URL(product.onlineStoreUrl); } catch { fail('FEED_SOURCE_UNKNOWN: published storefront link missing'); }
  if (url.protocol !== 'https:' || url.hostname !== EXPECTED_DOMAIN || url.port || url.username || url.password ||
