  url.search = ''; url.hash = ''; url.searchParams.set('variant', v.id.split('/').at(-1));
  if (!Array.isArray(product.media?.edges)) fail('FEED_SOURCE_UNKNOWN: image response incomplete');
  if (product.featuredMedia?.mediaContentType !== 'IMAGE' || !product.featuredMedia?.image?.url) {
    fail('FEED_SOURCE_UNKNOWN: actual featured product image required, video/model preview is not a substitute');
  }
  const image = product.featuredMedia.image.url;
  const bilder = product.media.edges.filter(m => m.node?.mediaContentType === 'IMAGE').map(m => m.node?.image?.url).filter(Boolean);
  return {
    id: record.feedId, sku: v.sku, handle: record.handle, gtin: sourceGtin(v),
    titel: product.title, beschreibung: product.beschreibung || product.title,
    link: url.href, bild: image,
    weitereBilder: bilder.filter(u => u !== image),
