export async function buildMerchantFeed({ identityMap, readShop, readPage, scan }) {
  const identity = validateIdentityMap(identityMap);
  if (!Number.isSafeInteger(scan) || scan < identity.entries.size) fail('FEED_LIMIT: explicit read ceiling must cover reviewed map');
  validateShopIdentity(await readShop());
  const productsSeen = new Map(), externalIds = new Set(), items = [];
  const queries = mappedQueries(identity); let reads = 0;
  for (const query of queries) {
    let cursor = null; const cursors = new Set();
    do {
      if (reads >= scan) fail('FEED_SOURCE_UNKNOWN: read ceiling reached before complete source');
      const data = await readPage({ q: query, after: cursor, first: Math.min(50, scan - reads) });
      const page = data?.products;
      if (!page || !Array.isArray(page.edges) || typeof page.pageInfo?.hasNextPage !== 'boolean') {
        fail('FEED_SOURCE_UNKNOWN: incomplete product page');
      }
      for (const edge of page.edges) {
        reads++; if (reads > scan) fail('FEED_LIMIT: response exceeded requested read ceiling');
        const x = edge?.node, record = identity.entries.get(x?.id);
        if (!record) fail('FEED_SOURCE_UNKNOWN: response includes unreviewed product');
        if (productsSeen.has(x.id)) fail('FEED_SOURCE_UNKNOWN: duplicate product response');
        const product = sourceProduct(x, record), decision = pruefeProdukt(product);
        if (!decision.ok) fail(`FEED_REVIEW_REQUIRED: existing mapped item rejected (${decision.grund})`);
        const item = feedItem(product);
        if (typeof item !== 'string' || !item.trim()) fail('FEED_SOURCE_UNKNOWN: serializer returned no mapped item');
        if (externalIds.has(record.feedId)) fail('FEED_IDENTITY_CONFLICT: duplicate feed ID');
        productsSeen.set(x.id, x); externalIds.add(record.feedId); items.push(item);
      }
      if (!page.pageInfo.hasNextPage) break;
      const next = page.pageInfo.endCursor;
      if (typeof next !== 'string' || !next || next === cursor || cursors.has(next) || !page.edges.length) {
        fail('FEED_SOURCE_UNKNOWN: invalid or repeated cursor');
      }
      cursors.add(next); cursor = next;
    } while (true);
  }
  if (productsSeen.size !== identity.entries.size || externalIds.size !== identity.externalIds.size ||
      [...identity.externalIds].some(id => !externalIds.has(id))) fail('FEED_IDENTITY_UNKNOWN: candidate would add/remove mapped identities');
  const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0" xmlns:g="http://base.google.com/ns/1.0">\n<channel>\n<title>LuxeStyle CH — Produktfeed</title>\n<link>https://luxestyle.ch</link>\n<description>LuxeStyle Schweizer Mode-Shop — Google-Merchant-Feed</description>\n${items.join('\n')}\n</channel>\n</rss>`;
  return { xml, itemCount: items.length, productsRead: reads, identityIdsPreserved: true,
    sourceSnapshotSha256: identity.source.sourceSnapshotSha256, dataSourceId: identity.source.dataSourceId,
    merchantAccountId: EXPECTED_MERCHANT, artifactOnly: true, merchantPushPerformed: false };
}

export function writeCandidate(file, xml, { allowReplace = false } = {}) {
  const target = path.resolve(file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  const temp = `${target}.tmp-${process.pid}`;
  let fd, owned = false;
  try {
    fd = fs.openSync(temp, 'wx', 0o600);
    owned = true;
    fs.writeFileSync(fd, xml); fs.fsyncSync(fd); fs.closeSync(fd); fd = undefined;
    // Atomic no-clobber: existsSync+rename would replace a racing file or symlink.
    if (allowReplace) fs.renameSync(temp, target);
    else {
      try { fs.linkSync(temp, target); }
      catch (error) { if (error.code === 'EEXIST') fail('FEED_OUTPUT_EXISTS: explicit replacement approval required'); throw error; }
      fs.unlinkSync(temp);
    }
  }
  finally { if (fd !== undefined) fs.closeSync(fd); if (owned && fs.existsSync(temp)) fs.unlinkSync(temp); }
}

export function validateOutputPath(output, mapFile) {
  const target = path.resolve(output), source = fs.realpathSync(mapFile);
  let ancestor = target, suffix = [];
  while (!fs.existsSync(ancestor)) {
    // lstat catches broken symlinks which existsSync intentionally treats as absent.
    try { if (fs.lstatSync(ancestor).isSymbolicLink()) fail('FEED_OUTPUT_ALIAS: broken output symlink'); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
    const parent = path.dirname(ancestor);
    if (parent === ancestor) fail('FEED_OUTPUT_UNKNOWN: output parent unavailable');
    suffix.unshift(path.basename(ancestor)); ancestor = parent;
  }
  const canonical = path.join(fs.realpathSync(ancestor), ...suffix);
  if (canonical === source) fail('FEED_OUTPUT_ALIAS: output must not replace the identity map');
  if (fs.existsSync(target)) {
    const a = fs.statSync(target), b = fs.statSync(source);
    if (a.dev === b.dev && a.ino === b.ino) fail('FEED_OUTPUT_ALIAS: output aliases the identity map');
  }
  return target;
}

export async function runMerchantFeed({ env = process.env, gql = shopifyGql, fetchFn = globalThis.fetch, write = writeCandidate } = {}) {
  const shop = normalizeShopifyHost(env.SHOPIFY_SHOP || EXPECTED_SHOP);
  if (shop !== EXPECTED_SHOP) fail('FEED_SHOP_MISMATCH: unexpected Shopify host');
  if (!env.FEED_IDENTITY_MAP) fail('FEED_IDENTITY_UNKNOWN: FEED_IDENTITY_MAP required before credential use');
  let map; try { map = JSON.parse(fs.readFileSync(env.FEED_IDENTITY_MAP, 'utf8')); }
  catch { fail('FEED_IDENTITY_UNKNOWN: map missing/unreadable/malformed; do not initialise a replacement'); }
  const identity = validateIdentityMap(map);
  const out = validateOutputPath(env.OUT || path.join(ROOT, 'automation', 'autopilot', 'google-merchant-feed.candidate.xml'), env.FEED_IDENTITY_MAP);
  if (env.FEED_QUERY || env.SORT || env.REVERSE) fail('FEED_SCOPE: broad query/sort overrides are unsupported; use reviewed map');
  if (env.VERSAND_LAND !== undefined || env.VERSAND_PREIS !== undefined) {
    fail('FEED_SHIPPING_REVIEW_REQUIRED: legacy per-item shipping overrides require a separately verified policy');
  }
  const scan = env.SCAN === undefined ? identity.entries.size : Number(env.SCAN);
  if (!Number.isSafeInteger(scan) || scan < identity.entries.size) fail('FEED_LIMIT: SCAN must cover the reviewed map');
  let token = env.SHOPIFY_ADMIN_TOKEN;
  if (!token) {
    const secret = shopifyClientSecret(env.SHOPIFY_CLIENT_SECRET);
    if (!env.SHOPIFY_CLIENT_ID || !secret) fail('FEED_AUTH: Shopify credentials unavailable');
    let response; try { response = await fetchFn(`https://${shop}/admin/oauth/access_token`, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(30000),
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ client_id: env.SHOPIFY_CLIENT_ID, client_secret: secret, grant_type: 'client_credentials' }),
    }); } catch { fail('FEED_AUTH: token request failed'); }
    if (!response.ok) fail(`FEED_AUTH: token request HTTP ${response.status}`);
    let payload; try { payload = await response.json(); } catch { fail('FEED_AUTH: token response unreadable'); }
    if (typeof payload?.access_token !== 'string' || !payload.access_token) fail('FEED_AUTH: token unavailable');
    token = payload.access_token;
  }
  const result = await buildMerchantFeed({ identityMap: map, scan,
    readShop: async () => (await gql(shop, API, token, SHOP_QUERY, {}))?.shop,
    readPage: variables => gql(shop, API, token, PAGE_QUERY, variables),
  });
  write(out, result.xml, { allowReplace: env.FEED_ALLOW_REPLACE === '1' });
  return { ...result, output: out };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { const result = await runMerchantFeed(); console.log(`Merchant XML candidate: ${result.itemCount} items; IDs preserved; no Google push.`); }
  catch (error) { console.error(error.message); process.exitCode = 1; }
}

