+  variants: { pageInfo: { hasNextPage: false }, edges: [{ node: { id: record(n).variantId,
+    sku: 'CJ-RETAILER-SKU', price: '34.90', compareAtPrice: null, availableForSale: true, barcodes: barcode() } }] } });
+const page = products => ({ products: { edges: products.map(node => ({ node })), pageInfo: { hasNextPage: false, endCursor: null } } });
+const build = (products = [product()], overrides = {}) => buildMerchantFeed({ identityMap: map(products.length),
+  scan: products.length, readShop: async () => shop(), readPage: async () => page(products), ...overrides });
+const temp = () => fs.mkdtempSync(path.join(os.tmpdir(), 'luxe-merchant-offline-'));
+
+test('preserves existing opaque ID/exclusion and never substitutes retailer identifiers', async () => {
+  const result = await build();
+  assert.equal(result.itemCount, 1); assert.equal(result.merchantPushPerformed, false);
+  assert.match(result.xml, /<g:id>WALLET-BLK<\/g:id>/);
+  assert.match(result.xml, /<g:excluded_destination>Shopping_ads<\/g:excluded_destination>/);
+  assert.doesNotMatch(result.xml, /<g:(?:brand|mpn|identifier_exists)>|<g:excluded_destination>Free_listings/);
+  assert.match(result.xml, /produkt-1\?variant=101/);
+  assert.doesNotMatch(result.xml, /<g:shipping>/); // No unverified CHF7 override of Merchant account policy/CHF50.
+});
+test('mapped reads cover only reviewed IDs; no status-wide second pass', async () => {
+  const queries = []; const products = [product(), product(2)];
+  await build(products, { readPage: async variables => { queries.push(variables); return page(products); } });
+  assert.deepEqual(queries, [{ q: 'id:1 OR id:2', after: null, first: 2 }]);
+});
+test('known source absence is explicit and does not invent restrictions', () => {
+  assert.deepEqual(parseExcludedDestinations({ excludedDestination: null }), []);
+  assert.deepEqual(parseExcludedDestinations({ excludedDestination: { type: 'single_line_text_field', value: 'Free_listings' } }), ['Free_listings']);
+});
+for (const field of [undefined, {}, { type: 'list.single_line_text_field', value: '{' },
+  { type: 'json', value: '["Shopping_ads"]' }, { type: 'single_line_text_field', value: '' }]) {
+  test(`unknown exclusion input aborts whole candidate: ${JSON.stringify(field)}`, async () => {
+    const x = product(); if (field === undefined) delete x.excludedDestination; else x.excludedDestination = field;
+    await assert.rejects(build([x]), /FEED_SOURCE_UNKNOWN/);
+  });
+}
+test('unknown destination enum aborts instead of dropping the item', async () => {
+  const x = product(); x.excludedDestination.value = '["made_up"]';
+  await assert.rejects(build([x]), /excluded_destination/);
+});
+for (const value of [undefined, null, 0, 'false']) {
+  test(`unknown availability is never in_stock: ${JSON.stringify(value)}`, async () => {
+    const x = product(); x.variants.edges[0].node.availableForSale = value;
+    await assert.rejects(build([x]), /availability missing/);
+  });
+}
+test('explicit availability false stays out of stock', async () => {
+  const x = product(); x.variants.edges[0].node.availableForSale = false;
+  assert.match((await build([x])).xml, /<g:availability>out of stock/);
+});
+test('typed GTIN survives; CJ/SKU/ASIN is never used as MPN', async () => {
+  const x = product(); x.variants.edges[0].node.barcodes = barcode('4006381333931');
+  const xml = (await build([x])).xml;
+  assert.match(xml, /<g:gtin>4006381333931/); assert.doesNotMatch(xml, /<g:mpn>/);
+  assert.equal(sourceGtin({ barcodes: { edges: [{ node: { type: 'ASIN', value: 'B12345678' } }], pageInfo: { hasNextPage: false } } }), undefined);
+});
+test('incomplete or ambiguous barcode source aborts rather than guessing', () => {
+  assert.throws(() => sourceGtin({}), /complete exact-variant/);
+  assert.throws(() => sourceGtin({ barcodes: { ...barcode(), pageInfo: { hasNextPage: true } } }), /complete exact-variant/);
+  const codes = barcode('4006381333931'); codes.edges.push({ node: { type: 'GTIN', value: '5012345678900' } });
+  assert.throws(() => sourceGtin({ barcodes: codes }), /multiple GTINs/);
+});
+test('mapped exact variant and full single-variant scope are mandatory', async () => {
+  const wrong = product(); wrong.variants.edges[0].node.id = 'gid://shopify/ProductVariant/999';
+  await assert.rejects(build([wrong]), /FEED_VARIANT_UNKNOWN/);
+  const several = product(); several.variants.pageInfo.hasNextPage = true;
+  await assert.rejects(build([several]), /FEED_VARIANT_UNKNOWN/);
+});
+test('no empty tags, DRAFT activation, or broad rueckhol Merchant policy', async () => {
+  for (const tags of [[], null, [''], ['nicht-bewerben'], ['raucher-rueckhol-0809']]) {
+    const x = product(); x.tags = tags; await assert.rejects(build([x]), /FEED_SOURCE_UNKNOWN|FEED_REVIEW_REQUIRED/);
+  }
+  const x = product(); x.status = 'DRAFT'; await assert.rejects(build([x]), /FEED_SOURCE_UNKNOWN/);
+  assert.equal((await build()).itemCount, 1); // Existing Merchant-specific rueckhol-0907 policy unchanged.
+});
+test('safety review sees the full description beyond the old 900-character window', async () => {
+  const x = product(); x.beschreibung = 'A'.repeat(950) + ' Harry Potter';
+  await assert.rejects(build([x]), /FEED_REVIEW_REQUIRED/);
+  const y = product(); delete y.beschreibung;
+  await assert.rejects(build([y]), /full current product description/);
+});
+for (const price of [undefined, null, '', 'Infinity', '-1', 'NaN', '0']) {
+  test(`unknown/invalid exact variant price aborts: ${JSON.stringify(price)}`, async () => {
+    const x = product(); x.variants.edges[0].node.price = price;
+    await assert.rejects(build([x]), /positive exact-variant CHF price/);
+  });
+}
+test('product link, actual image and shop CHF identity cannot be guessed', async () => {
+  const x = product(); x.onlineStoreUrl = 'https://other.example/products/produkt-1';
+  await assert.rejects(build([x]), /storefront URL/);
+  const y = product(); y.featuredMedia = { mediaContentType: 'VIDEO', image: { url: 'https://cdn.shopify.com/preview.jpg' } };
+  await assert.rejects(build([y]), /actual featured product image/);
+  await assert.rejects(build([product()], { readShop: async () => ({ ...shop(), currencyCode: 'USD' }) }), /FEED_SHOP_MISMATCH/);
+});
+test('incomplete/full-set mismatch, unknown product and duplicate response all abort', async () => {
+  await assert.rejects(build([product()], { identityMap: map(2), scan: 2 }), /candidate would add\/remove/);
+  await assert.rejects(build([product(2)], { identityMap: map() }), /unreviewed product/);
+  await assert.rejects(build([product(), product()], { identityMap: map(2), scan: 2 }), /duplicate product response/);
+});
+test('bounded pagination never converts truncation to a complete replacement', async () => {
+  const p = page([product()]); p.products.pageInfo = { hasNextPage: true, endCursor: 'cursor-a' };
+  await assert.rejects(build([product()], { readPage: async () => p }), /read ceiling reached/);
+  p.products.pageInfo.endCursor = null;
+  await assert.rejects(build([product()], { readPage: async () => p }), /invalid or repeated cursor/);
+});
+test('identity proof shape missing/wrong/duplicate never initialises a new source', () => {
+  for (const value of [undefined, {}, { ...map(), complete: false }, { ...map(), merchantAccountId: 'other' },
+    { ...map(), sourceSnapshotSha256: 'x' }, { ...map(), entries: [record(), record()] }]) assert.throws(() => validateIdentityMap(value), /FEED_IDENTITY/);
+});
+test('module import performs no network, token fetch, file output or process exit', () => {
+  const module = fileURLToPath(new URL('./merchant_feed.mjs', import.meta.url));
+  const result = execFileSync(process.execPath, ['--input-type=module', '-e',
+    'globalThis.fetch=()=>{throw new Error("NETWORK-FORBIDDEN")};await import('+JSON.stringify(module)+');console.log("IMPORT-ONLY")'],
+    { encoding: 'utf8', env: { ...process.env, SHOPIFY_ADMIN_TOKEN: 'OFFLINE-FAKE-NOT-A-CREDENTIAL' } });
+  assert.equal(result.trim(), 'IMPORT-ONLY');
+});
+test('map, identity and output aliases fail before any credential/network use', async () => {
+  const dir = temp(), file = path.join(dir, 'identity.json'); fs.writeFileSync(file, JSON.stringify(map()));
+  let calls = 0; const noNetwork = async () => { calls++; throw new Error('network forbidden'); };
+  await assert.rejects(runMerchantFeed({ env: {}, fetchFn: noNetwork, gql: noNetwork }), /FEED_IDENTITY_UNKNOWN/);
+  await assert.rejects(runMerchantFeed({ env: { SHOPIFY_SHOP: 'other.myshopify.com', FEED_IDENTITY_MAP: file }, fetchFn: noNetwork, gql: noNetwork }), /FEED_SHOP_MISMATCH/);
+  for (const output of [file, path.join(dir, '.', 'identity.json')]) {
+    await assert.rejects(runMerchantFeed({ env: { FEED_IDENTITY_MAP: file, OUT: output, FEED_ALLOW_REPLACE: '1' }, fetchFn: noNetwork, gql: noNetwork }), /FEED_OUTPUT_ALIAS/);
+  }
+  await assert.rejects(runMerchantFeed({ env: { FEED_IDENTITY_MAP: file, OUT: path.join(dir, 'candidate.xml'), VERSAND_PREIS: '7' }, fetchFn: noNetwork, gql: noNetwork }), /FEED_SHIPPING_REVIEW_REQUIRED/);
+  const hard = path.join(dir, 'hard.xml'); fs.linkSync(file, hard); assert.throws(() => validateOutputPath(hard, file), /FEED_OUTPUT_ALIAS/);
+  const sym = path.join(dir, 'sym.xml'); fs.symlinkSync(file, sym); assert.throws(() => validateOutputPath(sym, file), /FEED_OUTPUT_ALIAS/);
+  assert.equal(calls, 0); fs.rmSync(dir, { recursive: true });
+});
+test('output is a candidate only; validation failure preserves existing file and no write', async () => {
+  const dir = temp(), file = path.join(dir, 'identity.json'), output = path.join(dir, 'candidate.xml');
+  fs.writeFileSync(file, JSON.stringify(map())); fs.writeFileSync(output, 'EXISTING');
+  let writes = 0; const env = { FEED_IDENTITY_MAP: file, OUT: output, SHOPIFY_ADMIN_TOKEN: 'OFFLINE-FAKE-NOT-A-CREDENTIAL' };
+  const gql = async (_shop, api, _token, query) => { assert.equal(api, API); return query === SHOP_QUERY ? { shop: shop() } : page([]); };
+  await assert.rejects(runMerchantFeed({ env, gql, write: () => writes++ }), /candidate would add\/remove/);
+  assert.equal(writes, 0); assert.equal(fs.readFileSync(output, 'utf8'), 'EXISTING');
+  fs.rmSync(dir, { recursive: true });
+});
+test('429/Auth/error remains failure rather than an empty feed; no file write', async () => {
+  const dir = temp(), file = path.join(dir, 'identity.json'); fs.writeFileSync(file, JSON.stringify(map()));
+  for (const message of ['GraphQL: HTTP 429', 'GraphQL: HTTP 401', 'unreadable response']) {
+    let writes = 0;
+    await assert.rejects(runMerchantFeed({ env: { FEED_IDENTITY_MAP: file, OUT: path.join(dir, 'candidate.xml'), SHOPIFY_ADMIN_TOKEN: 'FAKE' },
+      gql: async () => { throw new Error(message); }, write: () => writes++ }), new RegExp(message));
+    assert.equal(writes, 0);
+  }
+  fs.rmSync(dir, { recursive: true });
+});
+test('atomic candidate default never overwrites existing files or broken symlinks', () => {
+  const dir = temp(), output = path.join(dir, 'candidate.xml');
+  fs.writeFileSync(output, 'OLD'); assert.throws(() => writeCandidate(output, 'NEW'), /FEED_OUTPUT_EXISTS/);
+  assert.equal(fs.readFileSync(output, 'utf8'), 'OLD'); fs.unlinkSync(output);
+  fs.symlinkSync(path.join(dir, 'missing'), output); assert.throws(() => writeCandidate(output, 'NEW'), /FEED_OUTPUT_EXISTS/);
+  assert.equal(fs.lstatSync(output).isSymbolicLink(), true); fs.unlinkSync(output);
+  writeCandidate(output, 'NEW'); assert.equal(fs.readFileSync(output, 'utf8'), 'NEW');
+  writeCandidate(output, 'APPROVED', { allowReplace: true }); assert.equal(fs.readFileSync(output, 'utf8'), 'APPROVED');
+  assert.deepEqual(fs.readdirSync(dir), ['candidate.xml']); fs.rmSync(dir, { recursive: true });
+});
+test('an existing temporary checkpoint is preserved, never unlinked after failed ownership', () => {
+  const dir = temp(), output = path.join(dir, 'candidate.xml'), checkpoint = `${output}.tmp-${process.pid}`;
+  fs.writeFileSync(checkpoint, 'OTHER-WORK'); assert.throws(() => writeCandidate(output, 'NEW'), /EEXIST/);
+  assert.equal(fs.readFileSync(checkpoint, 'utf8'), 'OTHER-WORK'); assert.equal(fs.existsSync(output), false);
+  fs.rmSync(dir, { recursive: true });
+});
+test('query uses explicit exclusion alias and schema-current image/barcodes fields', () => {
+  assert.match(PAGE_QUERY, /excludedDestination: metafield/); assert.match(PAGE_QUERY, /barcodes\(first:20\)/);
+  assert.doesNotMatch(PAGE_QUERY, /metafields\(first:12|featuredImage|\bbarcode\s|description\(truncateAt/);
+});

queries.PAGE_QUERY:
query MerchantCandidatePage($q:String!,$after:String,$first:Int!){
  products(first:$first, query:$q, after:$after){
    pageInfo{ hasNextPage endCursor }
    edges{ node{
      id status title handle onlineStoreUrl vendor productType tags
      beschreibung: description
      featuredMedia{ mediaContentType ... on MediaImage { image { url } } }
      media(first:4){ edges{ node{ mediaContentType ... on MediaImage { image { url } } } } }
      excludedDestination: metafield(namespace:"mm-google-shopping",key:"excluded_destination"){ type value }
      googleKategorie: metafield(namespace:"mm-google-shopping",key:"google_product_category"){ value }
      altersgruppe: metafield(namespace:"mm-google-shopping",key:"age_group"){ value }
      geschlecht: metafield(namespace:"mm-google-shopping",key:"gender"){ value }
      zustand: metafield(namespace:"mm-google-shopping",key:"condition"){ value }
      variants(first:1){ pageInfo{ hasNextPage } edges{ node{
        id sku price compareAtPrice availableForSale
        barcodes(first:20){ pageInfo{ hasNextPage } edges{ node{ type value } } }
      } } }
    } }
  }
}

